configfiles.configfile:
set -eu
ref="\$1"; output="\$2"; files="\$3"
[ -n "\$files" ] || { echo "no MAF pieces reached the job" >&2; exit 1; }
case "\$ref" in ''|*[!A-Za-z0-9_]*) echo "reference name must be letters, digits or _: \$ref" >&2; exit 1;; esac
\#\# The order is read from the content: the pieces arrive in whatever order the job is given them (a
\#\# UDT's mapped multiple input is an identifier-keyed object), and a piece's name is not available.
\#\# Pass 1 reads every piece for its first reference start, last reference end and sequence; pass 2
\#\# writes the pieces in start order. GNU awk, never BusyBox awk: BusyBox truncates on a failed write
\#\# and exits 0, gawk fails, and close() is checked as well.
gawk -v ref="\$ref" -v out="\$output" -v list="\$files" '
function die(m) { print "maf_concat: " m > "/dev/stderr"; failed = 1; exit 1 }
BEGIN {
    n = split(list, F, ",")
    m = 0
    for (i = 1; i <= n; i++) {
        hdr = ""; inb = 0; want = 0; nb = 0; seq = ""; first = -1; last = -1; maxend = -1; ln = 0
        while ((r = (getline line < F[i])) > 0) {
            ln++
            if (substr(line, 1, 1) == "#") {
                if (hdr == "" && line ~ /^\#\#maf version=1 scoring=/) hdr = line
                continue
            }
            if (line ~ /^[ \t]*\$/) {
                if (want) die("piece " i " has a block with no s line at line " ln)
                inb = 0; continue
            }
            c = substr(line, 1, 1)
            if (c == "a" && (line == "a" || substr(line, 2, 1) == " ")) {
                if (want) die("piece " i " has a block with no s line at line " ln)
                inb = 1; want = 1; nb++; continue
            }
            if (!inb) die("piece " i " has a line outside a block at line " ln ": " substr(line, 1, 60))
            if (!want) continue
            \#\# the first s line of a block is the reference row
            want = 0
            if (c != "s" || split(line, f, " ") != 7) die("piece " i " line " ln " is not an s line, and a block starts with the reference row")
            if (index(f[2], ref ".") != 1) die("the reference row at line " ln " of piece " i " is " f[2] ", not " ref ".<sequence>")
            s = substr(f[2], length(ref) + 2)
            st = f[3] + 0; en = st + f[4]
            if (seq == "") { seq = s; first = st }
            else if (s != seq) die("piece " i " holds two reference sequences, " seq " and " s)
            if (st < last) die("the reference start goes backwards in piece " i " at line " ln ": " st " after " last)
            last = st
            if (en > maxend) maxend = en
        }
        if (r < 0) die("cannot read piece " i ": " F[i])
        close(F[i])
        if (want) die("piece " i " ends in a block with no s line")
        if (header == "") header = hdr
        if (nb == 0) continue
        if (hdr == "") die("piece " i " has blocks but no \#\#maf header")
        m++; P[m] = F[i]; S[m] = first; E[m] = maxend; Q[m] = seq; H[m] = hdr; B[m] = nb; nblocks += nb
    }
    \#\# a handful to a few hundred pieces: an insertion sort on the first reference start is plenty
    for (i = 2; i <= m; i++) {
        p = P[i]; s0 = S[i]; e0 = E[i]; q0 = Q[i]; h0 = H[i]; b0 = B[i]
        for (j = i - 1; j >= 1 && S[j] > s0; j--) { P[j + 1] = P[j]; S[j + 1] = S[j]; E[j + 1] = E[j]; Q[j + 1] = Q[j]; H[j + 1] = H[j]; B[j + 1] = B[j] }
        P[j + 1] = p; S[j + 1] = s0; E[j + 1] = e0; Q[j + 1] = q0; H[j + 1] = h0; B[j + 1] = b0
    }
    for (i = 2; i <= m; i++) {
        if (Q[i] != Q[1]) die("the pieces cover more than one reference sequence: " Q[1] " and " Q[i])
        if (E[i - 1] > S[i]) die("pieces overlap on " Q[i] ": one ends at " E[i - 1] ", the next starts at " S[i])
    }
    if (m > 0) header = H[1]
    if (header == "") header = "\#\#maf version=1"
    print header > out
    for (i = 1; i <= m; i++) {
        inb = 0
        while ((r = (getline line < P[i])) > 0) {
            if (substr(line, 1, 1) == "#") continue
            if (line ~ /^[ \t]*\$/) { if (inb) { print "" > out; inb = 0 } ; continue }
            if (substr(line, 1, 1) == "a" && inb) print "" > out
            inb = 1
            print line > out
        }
        if (r < 0) die("cannot read piece " P[i])
        close(P[i])
        if (inb) print "" > out
    }
    print "\#\#eof maf" > out
    if (close(out) != 0) die("cannot write " out)
    print "pieces: " n " (" m " with blocks)"
    if (m == 0) print "warning: no piece has blocks; the output is a header and \#\#eof maf only"
    else print "sequence: " Q[1] ", " nblocks " blocks, reference " S[1] " to " E[m]
    \#\# no main input: leave from BEGIN, or gawk would go on to read stdin for the END rule
    exit 0
}
END { if (failed) exit 1 }'
